{
  "name": "opencode-agent-plus",
  "version": "0.4.0",
  "description": "OpenCode plugin: safe-command auto-allow (no prompt for read-only calls), per-agent chat_template_kwargs (enable_thinking), sampling settings and system reminders from agent frontmatter. For llama.cpp, LiteLLM and OpenAI-compatible providers.",
  "license": "MIT",
  "author": "Anoosh Ahmadi",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Anooshiravan/opencode-agent-plus.git"
  },
  "keywords": [
    "opencode", "opencode-plugin", "opencode-agent", "agent", "agents", "frontmatter",
    "llama.cpp", "llama-cpp", "litellm", "openai-compatible", "local-llm",
    "chat_template_kwargs", "chat-template-kwargs", "enable_thinking", "thinking", "reasoning",
    "temperature", "sampling", "top_p", "top_k", "min_p",
    "system-reminder", "reminder", "qwen"
  ],
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": ["src"],
  "peerDependencies": {
    "@opentui/core": ">=0.7.0",
    "@opentui/solid": ">=0.7.0",
    "solid-js": ">=1.9.0"
  }
}
